// Called by the database, never by the site: migration 035's trigger runs
// n8n_post('deskdev-lead-intake', { lead_id }) once intake_site_lead has
// recorded a new, non-spam lead. Only the id travels; everything else is read
// back from the database, so a forged body can at most name an existing lead.
const body = $input.first().json.body || {};
const leadId = String(body.lead_id || '').trim().toLowerCase();
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/.test(leadId)) {
  throw new Error('deskdev-lead-intake: body.lead_id must be a uuid');
}
return [{ json: { lead_id: leadId } }];

// Decide everything once, so every later node reads the same facts.
// The database is the system of record: intake_site_lead (migration 034)
// already stored, scored and assigned the lead and notified the team in-app.
// This workflow only adds side effects: the prospect's auto-reply, the team
// email, a Sheets row and the run log. Any of them failing loses no lead.
const APP_URL = 'https://workspace.nixgensolutions.com';
const SITE_URL = 'https://nixgensolutions.com';
const FALLBACK_TO = 'nixgensolutions@gmail.com'; // company inbox: only when no teammate qualifies
// A webhook that arrives late (n8n asleep, a replay) must not send a
// "thanks, we got it" days after the fact.
const AUTO_REPLY_MAX_AGE_MS = 24 * 60 * 60 * 1000;
const EMAIL_RE = /^[^\s@,;<>"']+@[^\s@,;<>"']+\.[^\s@,;<>"']+$/;

const rows = (name) => $(name).all().map(i => i.json).flat().filter(r => r && typeof r === 'object');
const leadId = $('Parse').first().json.lead_id;
const lead = rows('Lead').find(r => r.id === leadId);
// workspace_settings is a singleton keyed by id = true (migration 033).
const settings = rows('Settings').find(r => r.id === true) || {};
const priorReply = rows('Prior auto-reply').some(r => r.id);
const people = rows('Recipients')
  .filter(p => p.id && !p.deactivated_at && EMAIL_RE.test(String(p.email || '').trim()));

const skip = (reason) => [{ json: { process: false, lead_id: leadId, reason } }];
if (!lead) return skip('lead_not_found');
// Quarantined leads never trigger this workflow; checked again because a
// teammate may have marked it spam between the insert and this run.
if (lead.spam === true) return skip('spam');
// A CSV import of old enquiries is history, not news: no emails, no rows.
if (lead.form === 'import') return skip('import');
if (lead.stage === 'won' || lead.stage === 'lost') return skip('closed');

// Every value below is prospect-typed or teammate-typed text: escaped once,
// at the point it enters HTML. Subjects lose line breaks.
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const oneLine = (s, max) => String(s ?? '').replace(/[\r\n\t]+/g, ' ').replace(/\s{2,}/g, ' ').trim().slice(0, max);
const safeHttps = (u) => {
  try {
    const x = new URL(String(u ?? '').trim());
    return x.protocol === 'https:' && !x.username && !x.password ? x.href : '';
  } catch (e) {
    return '';
  }
};
const tz = (() => {
  const want = (settings.growth_business_hours || {}).tz || 'Asia/Manila';
  try { new Intl.DateTimeFormat('en-US', { timeZone: want }); return want; } catch (e) { return 'Asia/Manila'; }
})();
const when = (iso) => {
  const d = new Date(iso);
  if (!iso || Number.isNaN(d.getTime())) return '';
  return new Intl.DateTimeFormat('en-GB', { timeZone: tz, weekday: 'short', day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' }).format(d) + ' (' + tz + ')';
};

const services = Array.isArray(lead.services) ? lead.services.filter(Boolean).map(String) : [];
const prospectEmail = String(lead.email || '').trim();
const owner = people.find(p => p.id === lead.owner_id);

// ---- 1. Auto-reply to the prospect -------------------------------------------
// Off unless an admin switched it on (Settings → Growth). It never echoes the
// prospect's message, budget or links back: the form takes any address, so an
// echo would let anyone send our mail with their words to a stranger. Only a
// plain first name is used, and only when it looks like one.
const submittedAt = Date.parse(lead.last_submitted_at || lead.created_at || '');
const fresh = Number.isFinite(submittedAt) && Date.now() - submittedAt < AUTO_REPLY_MAX_AGE_MS;
let replyReason = '';
if (settings.growth_auto_reply !== true) replyReason = 'auto_reply_off';
else if (priorReply) replyReason = 'already_sent';
else if (lead.source !== 'website' || lead.form === 'email') replyReason = 'not_a_site_form';
else if (!EMAIL_RE.test(prospectEmail)) replyReason = 'no_valid_email';
else if (!fresh) replyReason = 'stale';
const autoReply = replyReason === '';

const first = String(lead.name || '').trim().split(/\s+/)[0] || '';
const greet = /^\p{L}[\p{L}'’-]{0,29}$/u.test(first) ? first : 'there';
const booking = safeHttps(settings.growth_booking_url);
const reply = autoReply ? {
  to: prospectEmail,
  subject: 'Thanks for contacting NixGen Solutions',
  html: `<div style="font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;color:#111;line-height:1.55;max-width:560px">
  <p>Hi ${esc(greet)},</p>
  <p>Thanks for reaching out to NixGen Solutions. We've received your message, and we'll respond within 12 hours.</p>
  ${booking ? `<p>Prefer to talk it through? <a href="${esc(booking)}">Pick a time for a call</a>.</p>` : ''}
  <p>If there's anything you'd like to add, just reply to this email.</p>
  <p style="margin-top:20px">The NixGen Solutions team<br><a href="${SITE_URL}" style="color:#2563eb">nixgensolutions.com</a></p>
</div>`,
} : null;

// ---- 2. Team email -------------------------------------------------------------
// The lead's owner, plus every Growth editor while "notify everyone" is on
// (growth_notify_all, the default). Admins when nobody else qualifies.
const growthEditors = settings.growth_notify_all === false ? [] : people.filter(p =>
  p.role === 'admin' || (p.permissions || {}).growth === 'edit');
let team = [owner, ...growthEditors].filter(Boolean);
if (!team.length) team = people.filter(p => p.role === 'admin');
const teamTo = [...new Set(team.map(p => String(p.email).trim().toLowerCase()))].join(',') || FALLBACK_TO;

const attr = lead.attribution && typeof lead.attribution === 'object' ? lead.attribution : {};
const touch = attr.last || attr.first || attr;
const campaign = [touch.utm_source, touch.utm_medium, touch.utm_campaign].filter(Boolean).map(String).join(' / ');
const referrer = touch.referrer ? String(touch.referrer) : '';
const score = Number.isFinite(Number(lead.score)) && lead.score !== null ? Number(lead.score) : null;
const link = `${APP_URL}/growth/leads?lead=${encodeURIComponent(lead.id)}`;

const row = (label, value, extra = '') => value === '' || value == null ? '' :
  `<tr><td style="padding:5px 12px 5px 0;color:#666;font-size:13px;vertical-align:top;white-space:nowrap">${label}</td><td style="padding:5px 0;font-size:14px;${extra}">${esc(value)}</td></tr>`;
const message = String(lead.message || '').slice(0, 4000);
const teamHtml = `<div style="font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;color:#111;max-width:640px">
  <h2 style="margin:0 0 4px">New lead: ${esc(lead.name || 'Website enquiry')}${lead.hot ? ' 🔥' : ''}</h2>
  <p style="margin:0 0 16px;color:#666">${esc(lead.company || 'No company given')}${lead.existing_client_id ? ' · existing client' : ''}</p>
  <table style="border-collapse:collapse">
    ${row('Email', prospectEmail)}
    ${row('Phone', lead.phone || '')}
    ${row('Services', services.join(', '))}
    ${row('Budget', lead.budget_band || '')}
    ${row('Timeline', lead.timeline || '')}
    ${row('Score', score === null ? '' : `${score}${lead.hot ? ' (hot)' : ''}`)}
    ${row('Owner', owner ? owner.full_name || owner.email : 'Unassigned')}
    ${row('Reply by', when(lead.sla_due_at), 'color:#b91c1c')}
    ${row('Source', [lead.source, lead.form].filter(Boolean).join(' · '))}
    ${row('Campaign', campaign)}
    ${row('Referrer', referrer.slice(0, 200))}
  </table>
  ${message ? `<p style="margin:16px 0 4px;color:#666;font-size:13px">Their message</p>
  <div style="white-space:pre-wrap;border-left:3px solid #e5e7eb;padding:4px 12px;font-size:14px">${esc(message)}</div>` : ''}
  <p style="margin-top:20px"><a href="${esc(link)}" style="background:#2563eb;color:#fff;text-decoration:none;padding:9px 14px;border-radius:8px;font-size:14px">Open the lead in DeskDev</a></p>
  <p style="margin-top:16px;color:#999;font-size:12px">${autoReply ? 'An auto-reply was sent to the prospect.' : 'No auto-reply was sent.'} Sent by n8n.</p>
</div>`;
const teamSubject = oneLine(`New lead: ${lead.name || 'Website enquiry'}${lead.company ? ` (${lead.company})` : ''}${lead.hot ? ' [hot]' : ''}`, 160);

// ---- 3. Sheets row -------------------------------------------------------------
// Same header as before (Name Company Email Notes). The prospect's message
// stays in the database: the sheet is a log, not a second copy of their words.
const now = new Date();
const sheet = {
  Timestamp: now.toISOString(),
  Date: new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Manila', year: 'numeric', month: '2-digit', day: '2-digit' }).format(now),
  Time: new Intl.DateTimeFormat('en-GB', { timeZone: 'Asia/Manila', hour: '2-digit', minute: '2-digit' }).format(now),
  Name: oneLine(lead.name, 200),
  Company: oneLine(lead.company, 200),
  Email: oneLine(prospectEmail, 254),
  Notes: [
    services.length ? `Services: ${services.join(', ')}` : '',
    lead.budget_band ? `Budget: ${lead.budget_band}` : '',
    lead.timeline ? `Timeline: ${lead.timeline}` : '',
    score === null ? '' : `Score: ${score}`,
    lead.form ? `Form: ${lead.form}` : '',
    `Lead: ${lead.id}`,
  ].filter(Boolean).map(s => oneLine(s, 300)).join(' · '),
};

return [{ json: {
  process: true,
  lead_id: lead.id,
  auto_reply: autoReply,
  auto_reply_reason: replyReason || 'sent',
  reply,
  team: { to: teamTo, count: teamTo.split(',').length, subject: teamSubject, html: teamHtml },
  sheet,
} }];
